@@ -55,6 +55,13 @@ func newDiffCmd(g *GlobalFlags) *cobra.Command {
 	c.Flags().StringVar(&o.CacheDir, "cache-dir", defaultCacheDir(), "module tarball cache directory")
 	c.Flags().StringVar(&o.KnownModulesFile, "known-modules-file", "", "override known-modules autocomplete file (mostly for tests)")
