diff --git a/apps/birdseye/cmd/diff_test.go b/apps/birdseye/cmd/diff_test.go
index 9462b7f..74e7c4e 100644
--- a/apps/birdseye/cmd/diff_test.go
+++ b/apps/birdseye/cmd/diff_test.go
@@ -234,3 +234,24 @@ func TestDiffDoesNotAddOnFailure(t *testing.T) {
 		t.Errorf("known-modules file should NOT exist after failure, stat err=%v", statErr)
 	}
 }
+
+func TestDiffValidArgsFunctionLoadsCache(t *testing.T) {
+	knownFile := filepath.Join(t.TempDir(), "known-modules")
+	if err := os.WriteFile(knownFile, []byte("alpha/aaa/aws\nbravo/bbb/gcp\n"), 0o600); err != nil {
+		t.Fatal(err)
+	}
+
+	root := NewRootCmd()
+	root.SetArgs([]string{"__complete", "diff", "--known-modules-file", knownFile, ""})
+	var stdout bytes.Buffer
+	root.SetOut(&stdout)
+	if err := root.ExecuteContext(context.Background()); err != nil {
+		t.Fatalf("execute completion: %v", err)
+	}
+	out := stdout.String()
+	for _, want := range []string{"alpha/aaa/aws", "bravo/bbb/gcp"} {
+		if !strings.Contains(out, want) {
+			t.Errorf("completion output missing %q\n%s", want, out)
+		}
+	}
+}
